mapper.select:

where lr.emp_id = #{empId}
  and lr.status = 'APPROVED'
  and lr.start_date <= #{to}
  and lr.end_date >= #{from}
order by lr.start_date


where lr.emp_id = #{empId}
  and lr.start_date <= #{to}
  and lr.end_date >= #{from}
order by lr.request_date desc, lr.leave_request_id desc


where lr.emp_id = #{empId}
  and lr.status in ('REQUESTED', 'APPROVED')
  and lr.start_date <= #{to}
  and lr.end_date >= #{from}
order by lr.start_date

mapper.sql:
where lr.approver_id = #{approverId}

	and lr.status in ('APPROVED', 'REJECTED')
	and lr.status = 'REQUESTED'

where lr.start_date <= #{search.to}
  and lr.end_date >= #{search.from}

	and e.department_id in
	#{deptId}


	and lr.leave_type_id = #{search.leaveTypeId}


	and (e.ename like concat('%', #{search.keyword}, '%') or e.emp_no like concat('%', #{search.keyword}, '%'))

mapper.update:
update leave_request
set status = 'APPROVED',
    approved_at = #{now}
where leave_request_id = #{leaveRequestId}
  and approver_id = #{approverId}
  and status = 'REQUESTED'

update leave_request
set status = 'REJECTED',
    approved_at = #{now},
    reject_reason = #{rejectReason}
where leave_request_id = #{leaveRequestId}
  and approver_id = #{approverId}
  and status = 'REQUESTED'

update leave_request
set status = 'CANCELED'
where leave_request_id = #{leaveRequestId}
  and emp_id = #{empId}
  and status = 'REQUESTED'
